INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37165, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある目的のために、物やサービスなどを使うこと。", "primary_collocate": null, "pronunciation": "りよう", "ipa": "ɾijoː", "syllable_count": 3, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "利用", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "企業はブランディングにおいて、色彩理論を巧みに利用している。", "target_word": "利用", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "これは心理学に基づいた人間の無意識の反応を利用したものだ。", "target_word": "利用", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "駅を利用する。", "target_word": "利用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "利用は無料です。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "図書館を利用しました。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古い道具を利用して棚を作った。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水を利用した水やりを始めた。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友人の親切を利用して得をした人がいる。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい技術を利用すれば、効率は上がる。", "target_word": "利用", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "利用する", "label": "活用"}, {"form": "利用できる", "label": "活用"}, {"form": "再利用", "label": "派生"}, {"form": "利用者", "label": "派生"}, {"form": "利用料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目的のために物を使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 7 words above tier T1 (max 2): 穀物 (Zipf 3.52), 豆類 (Zipf 2.6),