INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37164, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを使うこと。", "primary_collocate": null, "pronunciation": "りよう", "ipa": "ɾijoː", "syllable_count": 3, "sentences": [{"text": "バスを利用する。", "target_word": "利用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "利用は自由です。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "私は毎日、図書館を利用します。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この部屋は誰でも利用できます。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "ネットを利用して調べました。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利用の仕方を教えてください。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この券を利用すれば、安く乗れる。", "target_word": "利用", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "駅の利用が増えたので、新しい出口が作られた。", "target_word": "利用", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "利用する人が増えている。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "インターネットを利用した学習は、時間や場所に縛られないという利点がある。", "target_word": "利用", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "利用する", "label": "活用"}, {"form": "利用できる", "label": "活用"}, {"form": "再利用", "label": "派生"}, {"form": "利用者", "label": "派生"}, {"form": "利用料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物やサービスを使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.mo