INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物を体の中に取り入れ、分解して栄養として吸収すること。また、比喩的に情報などを理解して自分のものにすること。", "primary_collocate": null, "pronunciation": "しょうか", "ipa": "ɕoːka", "syllable_count": 3, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価が劇的に向上するのみならず、フィチン酸などの抗栄養因子も分解される。", "target_word": "消化", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "消化", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "消化に良い食事だ。", "target_word": "消化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "消化は胃の仕事です。", "target_word": "消化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野菜は消化されにくい。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "胃は食べ物の消化を助ける。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食べ過ぎると、消化が悪くなる。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい知識を消化して、自分の言葉で説明した。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "難しい本を読んでも、消化できなければ意味がない。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "食べたものが消化されるまで、およそ数時間かかる。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "消化する", "label": "活用"}, {"form": "消化される", "label": "活用"}, {"form": "消化不良", "label": "派生"}, {"form": "消化器", "label": "派生"}, {"form": "消化吸収", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 食べ物の分解吸収と情報の理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: フィチン (Zipf 1.72)','sentence 1 above tier T3: 6 words above tier T3 (max 3): 経る (Zipf 2.96), グルテン (Zipf 2.78), 網目 (Zipf 2.67), 緻密 (Zipf 3.25), 変容 (Zipf 3.25), 遂げる (Zipf 3.13)']::text[], 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べたものが体の中で小さく変わって、栄養になること。", "primary_collocate": null, "pronunciation": "しょうか", "ipa": "ɕoːka", "syllable_count": 3, "sentences": [{"text": "消化がいい。", "target_word": "消化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "胃で消化します。", "target_word": "消化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "パンは消化が早いです。", "target_word": "消化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食べ物は胃で消化される。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "よくかむと、消化がよくなる。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜遅く食べると消化に悪い。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子どもには消化のよいものを食べさせたい。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "消化を助けるために、食後に歩くようにしている。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "食べたものが消化されて栄養になる。", "target_word": "消化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "食物繊維は消化されにくいが、腸の働きを整えてくれる。", "target_word": "消化", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "消化する", "label": "活用"}, {"form": "消化される", "label": "活用"}, {"form": "消化不良", "label": "派生"}, {"form": "消化器", "label": "派生"}, {"form": "消化吸収", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 食べ物が体で栄養になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used 