INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35149, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "具体的な例を挙げて説明するときに使う言葉。たとえていえば。", "primary_collocate": null, "pronunciation": "たとえば", "ipa": "tatoeba", "syllable_count": 4, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "例えば", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "例えば、赤は情熱や緊急を、青は信頼を連想させる。", "target_word": "例えば", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "好きな果物は、例えばりんごです。", "target_word": "例えば", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "動物、例えば犬や猫が好きです。", "target_word": "例えば", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "スポーツなら、例えばサッカーがある。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本の料理には、例えば寿司や天ぷらがある。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "例えば、駅の近くに住めば、通勤が楽になる。", "target_word": "例えば", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "例えば彼のように毎日走れば、体力がつくだろう。", "target_word": "例えば", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "これはあくまで例えばの話だが、明日雪が降れば学校は休みになるだろう。", "target_word": "例えば", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "難しい言葉は、例えば絵や写真を使って説明すると分かりやすい。", "target_word": "例えば", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 具体例を挙げて説明する時の言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 穀物 (Zipf 3.52), 豆類 (Zipf 2.6), 主食 (Zipf 3.48), 阻ま (Zipf 2.97), 宿命 (Zipf 3.57)']::text[], 'bafd5310-271f-46d7-a9d3-