INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35148, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "れいを だす ときに いう ことば。", "primary_collocate": null, "pronunciation": "たとえば", "ipa": "tatoeba", "syllable_count": 4, "sentences": [{"text": "例えば、りんごです。", "target_word": "例えば", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好きな色は、例えば青です。", "target_word": "例えば", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "果物なら、例えばバナナがある。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "例えば、犬や猫を飼っている人は多い。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野菜、例えばにんじんを食べてほしい。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "運動を始めたいなら、例えば毎朝歩くといい。", "target_word": "例えば", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "例えば、雨の日に出かけなければならないとしたら、どうする。", "target_word": "例えば", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "駅から遠くない所、例えば商店街の近くに住みたい。", "target_word": "例えば", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "外国語を学ぶ方法は、例えばアプリを使ったり、本を読んだりすることだ。", "target_word": "例えば", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "例えばの話ですが、もし宝くじが当たったら、あなたは何に使いますか。", "target_word": "例えば", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 例を出すときに言う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,