INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52220, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まるで劇のように、変化や出来事が大きくて印象的な様子。", "primary_collocate": null, "pronunciation": "げきてき", "ipa": "ɡekiteki", "syllable_count": 4, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価が劇的に向上するのみならず、フィチン酸などの抗栄養因子も分解される。", "target_word": "劇的に", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "劇的な", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "変化は劇的だ。", "target_word": "劇的だ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "劇的な変化でした。", "target_word": "劇的な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天気が劇的に変わった。", "target_word": "劇的に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "薬を飲んで、病状は劇的に良くなった。", "target_word": "劇的に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼の人生は、その日を境に劇的に変わっていった。", "target_word": "劇的に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この映画は結末が劇的で、涙が止まらなかった。", "target_word": "劇的で", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劇的な逆転勝ちを見て、観客は大声で叫んだ。", "target_word": "劇的な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい政策が導入されたことで、町の様子は劇的に改善されたと言われている。", "target_word": "劇的に", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "劇的な", "label": "活用"}, {"form": "劇的に", "label": "活用"}, {"form": "劇的だ", "label": "活用"}, {"form": "劇的で", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | 変化や出来事が大きく印象的な様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 ab