INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36049, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間の区切りや、物事が始まる区切りのこと。", "primary_collocate": null, "pronunciation": "き", "ipa": "ki", "syllable_count": 1, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "期", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "期", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "新しい期が始まる。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "来月から新しい期に入ります。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春は、新しい期の始まりです。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新しい期に向けて、目標を立てた。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この期の目標を、みんなで決めた。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この会社は、今まさに成長の期を迎えている。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子どもの成長には、大切な期がいくつもあると言われている。", "target_word": "期", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "人生には、挑戦するべき期というものが必ず訪れるものだ。", "target_word": "期", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一期", "label": "助数詞"}, {"form": "二期", "label": "助数詞"}, {"form": "時期", "label": "派生"}, {"form": "期間", "label": "派生"}, {"form": "学期", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 時間や物事の始まりの区切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: