INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36048, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まった時間の区切り。", "primary_collocate": null, "pronunciation": "き", "ipa": "ki", "syllable_count": 1, "sentences": [{"text": "期が終わる。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "来月から新しい期が始まります。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この期は忙しいです。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年を二つの期に分ける。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前の期より売り上げが増えた。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一つの期が終わるごとに、成績が出る。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "期の終わりに、みんなで会議を開いた。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この期のうちに、計画を立てておかなければならない。", "target_word": "期", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "期の初めに決めた目標を、最後まで守ることができた。", "target_word": "期", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "学校では一年が三つの期に分けられていて、期ごとに試験が行われる。", "target_word": "期", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "一期", "label": "助数詞"}, {"form": "二期", "label": "助数詞"}, {"form": "時期", "label": "派生"}, {"form": "期間", "label": "派生"}, {"form": "学期", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 決まった時間の区切りのこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.m