INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52572, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の本質や真理を明らかにするために、深く考えたり調査したりすること。", "primary_collocate": null, "pronunciation": "たんきゅう", "ipa": "tankʲɯː", "syllable_count": 4, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "探究", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "探究", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "探究は終わらない。", "target_word": "探究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "真理を探究する。", "target_word": "探究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先生は科学を探究しています。", "target_word": "探究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は生涯、言葉の探究を続けた。", "target_word": "探究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然の不思議を探究して、論文にまとめた。", "target_word": "探究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子どもたちが探究する力を育てたい。", "target_word": "探究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探究を重ねた結果、新しい事実が明らかになった。", "target_word": "探究", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "この学校では、生徒が自ら問いを立てて探究する授業を行っている。", "target_word": "探究", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "探究する", "label": "活用"}, {"form": "探究した", "label": "活用"}, {"form": "探究心", "label": "派生"}, {"form": "探究者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 本質を深く考え調べ明らかにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) 