INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52968, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「オート」は接頭語で、自動的な、または自己のという意味を表します。主に外来語の一部として使われます。", "primary_collocate": null, "pronunciation": "おーと", "ipa": "oːto", "syllable_count": 3, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "オート", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "オートクチュールの持つ絶対的な希少性と排他性は、逆説的にマス市場におけるトレンドの源泉として機能している。", "target_word": "オート", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "オートロックの家に住む。", "target_word": "オート", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "オートフォーカスで写真を撮った。", "target_word": "オート", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この車にはオートライトがついている。", "target_word": "オート", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "オートクルーズを使うと運転が楽になる。", "target_word": "オート", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "オートモードに切り替えてください。", "target_word": "オート", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "オートチャージのカードを持っている。", "target_word": "オート", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "オートロックは鍵なしで閉まる。", "target_word": "オート", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "オートドアの前に立つと、扉が開く。", "target_word": "オート", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "オートロック", "label": "派生"}, {"form": "オートフォーカス", "label": "派生"}, {"form": "オートクチュール", "label": "派生"}], "register": "plain", "sense_fingerprint": "接頭辞 | 自動的や自己のを表す語頭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type)