INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53108, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物や果物、鉱物などを自然から取り出すこと。収穫すること。また、情報を集めたり記録したりすること。", "primary_collocate": null, "pronunciation": "とれる", "ipa": "toɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "採れた", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "畑で野菜が採れる。", "target_word": "採れる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この山ではきのこが採れます。", "target_word": "採れます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年は米がたくさん採れた。", "target_word": "採れた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海で採れた魚を食べた。", "target_word": "採れた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この島ではいい塩が採れる。", "target_word": "採れる", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地元で採れた果物を買った。", "target_word": "採れた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山奥の川では砂金も採れるそうだ。", "target_word": "採れる", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨が少なかったので、今年は思うように作物が採れなかった。", "target_word": "採れなかった", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "農家の人は、朝に採れたばかりの野菜を店に運ぶ。", "target_word": "採れた", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "採れない", "label": "活用"}, {"form": "採れます", "label": "活用"}, {"form": "採れた", "label": "活用"}, {"form": "採れて", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 野菜や鉱物などが自然から取れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = 