INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53107, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "木の実や野菜を手で集めることです。秋の日に公園や畑でよくします。お父さんと一緒に果物を摘むのもこれです。", "primary_collocate": null, "pronunciation": "とれる", "ipa": "toɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "畑でトマトが採れる。", "target_word": "採れる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋にはくりが採れます。", "target_word": "採れます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公園で木の実が採れた。", "target_word": "採れた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父と行った畑でなすが採れた。", "target_word": "採れた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この木はたくさん実が採れる。", "target_word": "採れる", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手でかんたんに採れる実です。", "target_word": "採れる", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高い所の実は手で採れない。", "target_word": "採れない", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "いちごがたくさん採れたので、家族で食べた。", "target_word": "採れた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋の畑では、おいしい野菜がいっぱい採れる。", "target_word": "採れる", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この公園では、秋にどんぐりが採れるそうです。", "target_word": "採れる", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "採れない", "label": "活用"}, {"form": "採れます", "label": "活用"}, {"form": "採れた", "label": "活用"}, {"form": "採れて", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 木の実や野菜を手で集められる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_