INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52216, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "創作活動や料理などを行うための仕事部屋。特に、パン職人や画家が作業に集中するための特別な空間。", "primary_collocate": null, "pronunciation": "あとりえ", "ipa": "atoɾie", "syllable_count": 4, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "アトリエ", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "アトリエ", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "画家はアトリエで絵を描く。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエは静かな場所だ。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼のアトリエを訪ねた。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "パン屋のアトリエで朝早くから働く。", "target_word": "アトリエ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友だちとアトリエに行って陶器を作った。", "target_word": "アトリエ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古い倉庫がアトリエに変わった。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエの窓から光が入ってくる。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女は自分のアトリエを持つのが夢だった。", "target_word": "アトリエ", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 創作や料理をするための仕事部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ドレープ (Zipf 1.9)','sentence 1 above tier T3: contains vocabulary far above tier T3: 張り詰める (Zipf 1.07)']::text[], '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52215, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンや絵などを つくる へやのことです。", "primary_collocate": null, "pronunciation": "あとりえ", "ipa": "atoɾie", "syllable_count": 4, "sentences": [{"text": "アトリエは広いです。", "target_word": "アトリエ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "ここは画家のアトリエです。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエで絵をかきます。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "パン屋のアトリエを見た。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエに入ってもいいですか。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女のアトリエは二階にある。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエで粘土の人形を作った。", "target_word": "アトリエ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "アトリエには絵の具のにおいがする。", "target_word": "アトリエ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏休みにアトリエへ行って、パンの作り方を習った。", "target_word": "アトリエ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "小さなアトリエだが、毎日きれいにそうじされている。", "target_word": "アトリエ", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | パンや絵などを作る部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors