INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "気持ちや心がしっかりと引き締まること。また、そのさま。", "primary_collocate": null, "pronunciation": "きんちょう", "ipa": "kintɕoː", "syllable_count": 4, "sentences": [{"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "緊張", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "緊張", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "とても緊張しています。", "target_word": "緊張しています", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "試験の前は緊張する。", "target_word": "緊張する", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "緊張で手が震えた。", "target_word": "緊張", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "発表の前に緊張をほぐすため、深呼吸をした。", "target_word": "緊張", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面接の部屋に入ると、緊張が一気に高まった。", "target_word": "緊張", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初めての舞台で、彼女は少し緊張した顔をしていた。", "target_word": "緊張した", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "大事な試合の前に、緊張が高まってきた。", "target_word": "緊張", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "緊張して、言葉が出なかった。", "target_word": "緊張して", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊張する", "label": "活用"}, {"form": "緊張した", "label": "活用"}, {"form": "緊張感", "label": "派生"}, {"form": "緊張させる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 心が引き締まること、またそのさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 見て取れ (Zipf 2.23)','sentence 1 above tier T2: contains vocabulary far above tier T2: 漲っ (Zipf 1.92)']::text[], '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とても大事なことや、これから何が起こるかわからないときの、心の感じです。", "primary_collocate": null, "pronunciation": "きんちょう", "ipa": "kintɕoː", "syllable_count": 4, "sentences": [{"text": "緊張しています。", "target_word": "緊張しています", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "試験の前は緊張する。", "target_word": "緊張する", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "緊張で手が冷たい。", "target_word": "緊張", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "発表のとき、緊張しました。", "target_word": "緊張しました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "緊張が止まらない。", "target_word": "緊張", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先生の前で緊張した。", "target_word": "緊張した", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "緊張をなくす方法を知りたい。", "target_word": "緊張", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初めての仕事で緊張して、水を飲んだ。", "target_word": "緊張して", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大事な試合の前に、緊張が高まってきた。", "target_word": "緊張", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "緊張した顔の友だちに、声をかけた。", "target_word": "緊張した", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊張する", "label": "活用"}, {"form": "緊張した", "label": "活用"}, {"form": "緊張感", "label": "派生"}, {"form": "緊張させる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 大事なときや先が不明なときの心の感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6345475f-52e7-4ea2-a273-77d60193bfe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_us