INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36965, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この実験では、水素と酸素から水を生成された。", "corrected_sentence": "この実験では、水素と酸素から水が生成された。", "error_description": "受身の「生成された」では、作られる物「水」の助詞は「を」ではなく「が」です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36965, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、主語には使えません。"}, {"text": "と", "is_correct": false, "explanation": "「水と生成する」では意味が通りません。"}, {"text": "が", "is_correct": true, "explanation": "作り出される「水」が主語なので「が」が合います。"}, {"text": "に", "is_correct": false, "explanation": "「水に生成する」は不自然です。"}], "correct_answer": "が", "explanations": {"へ": "「へ」は方向を表すので、主語には使えません。", "と": "「水と生成する」では意味が通りません。", "が": "作り出される「水」が主語なので「が」が合います。", "に": "「水に生成する」は不自然です。"}, "error_tags": {"へ": "direction", "と": "companion", "に": "target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "発生", "is_correct": false, "explanation": "「発生」は近い意味で、反対ではありません。"}, {"text": "記録", "is_correct": false, "explanation": "「記録」は反対ではありません。"}, {"text": "説明", "is_correct": false, "explanation": "「説明」は反対ではありません。"}, {"text": "消滅", "is_correct": true, "explanation": "作り出す「生成」の反対は、なくなる「消滅」です。"}], "correct_answer": "消滅", "explanations": {"発生": "「発生」は近い意味で、反対ではありません。", "記録": "「記録」は反対ではありません。", "説明": "「説明」は反対ではありません。", "消滅": "作り出す「生成」の反対は、なくなる「消滅」です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
