INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53108, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逸れる", "is_correct": false, "explanation": "「逸れる」（それる）は別の語で、音が一つ違います。"}, {"text": "採れる", "is_correct": true, "explanation": "「採れる」が聞こえた語です。"}, {"text": "濡れる", "is_correct": false, "explanation": "「濡れる」（ぬれる）は別の語で、音が一つ違います。"}, {"text": "溶ける", "is_correct": false, "explanation": "「溶ける」（とける）は別の語で、音が一つ違います。"}, {"text": "飛べる", "is_correct": false, "explanation": "「飛べる」（とべる）は別の語で、音が一つ違います。"}], "explanations": {"逸れる": "「逸れる」（それる）は別の語で、音が一つ違います。", "採れる": "「採れる」が聞こえた語です。", "濡れる": "「濡れる」（ぬれる）は別の語で、音が一つ違います。", "溶ける": "「溶ける」（とける）は別の語で、音が一つ違います。", "飛べる": "「飛べる」（とべる）は別の語で、音が一つ違います。"}, "sentence_index": null, "correct_answer": "採れる"}, "level_3": {"options": [{"text": "採れた", "is_correct": true, "explanation": "地元で収穫された穀物という意味で「採れた」が合います。"}, {"text": "笑った", "is_correct": false, "explanation": "穀物は笑いません。"}, {"text": "歌った", "is_correct": false, "explanation": "穀物は歌いません。"}, {"text": "光った", "is_correct": false, "explanation": "収穫の意味にはなりません。"}], "explanations": {"採れた": "地元で収穫された穀物という意味で「採れた」が合います。", "笑った": "穀物は笑いません。", "歌った": "穀物は歌いません。", "光った": "収穫の意味にはなりません。"}, "sentence_index": 0, "correct_answer": "採れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝から雨が降って、今年は元気がたくさん採れた。", "explanation": "「採れる」は元気には使えません。"}, {"text": "私は夜遅くまで宿題が採れて、とても眠い。", "explanation": "「採れる」に宿題をするという意味はありません。"}, {"text": "先週、友だちから大きな犬が採れた。", "explanation": "犬は採れるものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
