INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39547, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、並べる言い方になりません。"}, {"text": "と", "is_correct": true, "explanation": "「微かな緊張と、…好奇心」と並べる「と」が合います。"}, {"text": "まで", "is_correct": false, "explanation": "「まで」は範囲を表し、ここでは合いません。"}, {"text": "に", "is_correct": false, "explanation": "「緊張に、それを…上回る」では文がつながりません。"}], "correct_answer": "と", "explanations": {"へ": "「へ」は方向を表すので、並べる言い方になりません。", "と": "「微かな緊張と、…好奇心」と並べる「と」が合います。", "まで": "「まで」は範囲を表し、ここでは合いません。", "に": "「緊張に、それを…上回る」では文がつながりません。"}, "error_tags": {"へ": "direction", "まで": "limit", "に": "target"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "心配する", "is_correct": false, "explanation": "「心配する」は反対ではありません。"}, {"text": "準備する", "is_correct": false, "explanation": "「準備する」は反対ではありません。"}, {"text": "リラックスする", "is_correct": true, "explanation": "「緊張する」の反対は「リラックスする」です。"}, {"text": "練習する", "is_correct": false, "explanation": "「練習する」は反対ではありません。"}], "correct_answer": "リラックスする", "explanations": {"心配する": "「心配する」は反対ではありません。", "準備する": "「準備する」は反対ではありません。", "リラックスする": "「緊張する」の反対は「リラックスする」です。", "練習する": "「練習する」は反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
