INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51440, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "子供などが、楽しみのために自発的にする、決まった目的のない活動。", "primary_collocate": "", "pronunciation": "あそび", "ipa": "asobi", "syllable_count": 3, "sentences": [{"text": "ローマの子供は、木の馬のおもちゃで楽しい遊びをします。", "target_word": "遊び", "complexity_tier": "T4", "furigana": "あそび", "sentence_source": "mined"}, {"text": "庭の片隅に、子供のための遊び小屋を建てる計画が持ち上がった。", "target_word": "遊び", "complexity_tier": "T5", "furigana": "あそび", "sentence_source": "mined"}, {"text": "遊びが好きです。", "target_word": "遊び", "complexity_tier": "T1", "furigana": "あそび", "sentence_source": "generated"}, {"text": "子供たちは毎日遊びに夢中です。", "target_word": "遊び", "complexity_tier": "T2", "furigana": "あそび", "sentence_source": "generated"}, {"text": "雨の日は、家の中でできる遊びを考えた。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "この遊びは、昔から子供たちに人気がある。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "遊びの中で、子供は友達との付き合い方を学んでいく。", "target_word": "遊び", "complexity_tier": "T4", "furigana": "あそび", "sentence_source": "generated"}, {"text": "遊びだからといって、本気で取り組まなくていいわけではない。", "target_word": "遊び", "complexity_tier": "T5", "furigana": "あそび", "sentence_source": "generated"}, {"text": "兄は遊びで始めた絵を、いつの間にか仕事にしていた。", "target_word": "遊び", "complexity_tier": "T5", "furigana": "あそび", "sentence_source": "generated"}, {"text": "勉強ばかりでなく、遊びも子供の成長には欠かせない大切な時間である。", "target_word": "遊び", "complexity_tier": "T5", "furigana": "あそび", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊ぶ", "label": "派生"}, {"form": "遊び方", "label": "派生"}, {"form": "遊び場", "label": "派生"}, {"form": "遊び道具", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 子供が楽しみで自発的にする活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事や勉強ではなく、楽しく時間を過ごすこと。人を訪ねたり出かけたりすることも言う。", "primary_collocate": "", "pronunciation": "あそび", "ipa": "asobi", "syllable_count": 3, "sentences": [{"text": "週末は遊びに行きます。", "target_word": "遊び", "complexity_tier": "T2", "furigana": "あそび", "sentence_source": "generated"}, {"text": "今度、うちへ遊びに来てください。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "遊びで来たのではありません。", "target_word": "遊び", "complexity_tier": "T2", "furigana": "あそび", "sentence_source": "generated"}, {"text": "今日は仕事ではなく、友達と遊びの約束がある。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "大人になると、遊びの時間はだんだん減っていく。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "彼は遊びが上手で、いつも皆を楽しませてくれる。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "出張のついでに、遊びも兼ねて京都に寄った。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "遊びばかりしていて、宿題を忘れてしまった。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "あそび", "sentence_source": "generated"}, {"text": "久しぶりの遊びだったので、時間を忘れて楽しんだ。", "target_word": "遊び", "complexity_tier": "T4", "furigana": "あそび", "sentence_source": "generated"}, {"text": "休みの日の遊びを計画するのが、私の一番の楽しみである。", "target_word": "遊び", "complexity_tier": "T4", "furigana": "あそび", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊ぶ", "label": "派生"}, {"form": "遊び相手", "label": "派生"}, {"form": "遊び仲間", "label": "派生"}, {"form": "遊び心", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 仕事でなく楽しく過ごす出かけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51444, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物、乗り物などが速く移動する。また、ものが勢いよく動く。", "primary_collocate": "", "pronunciation": "はしる", "ipa": "haɕiɾɯ", "syllable_count": 3, "sentences": [{"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "走ります", "complexity_tier": "T3", "furigana": "はしります", "sentence_source": "mined"}, {"text": "放課後の静かな美術室で、私は窓辺の席につきクレヨンを走らせている。", "target_word": "走らせている", "complexity_tier": "T5", "furigana": "はしらせている", "sentence_source": "mined"}, {"text": "車が道を走る。", "target_word": "走る", "complexity_tier": "T1", "furigana": "はしる", "sentence_source": "generated"}, {"text": "電車は町の中を走ります。", "target_word": "走ります", "complexity_tier": "T2", "furigana": "はしります", "sentence_source": "generated"}, {"text": "犬が庭を走っている。", "target_word": "走っている", "complexity_tier": "T3", "furigana": "はしっている", "sentence_source": "generated"}, {"text": "馬が草原を走った。", "target_word": "走った", "complexity_tier": "T2", "furigana": "はしった", "sentence_source": "generated"}, {"text": "この道路は、毎日たくさんのトラックが走る。", "target_word": "走る", "complexity_tier": "T3", "furigana": "はしる", "sentence_source": "generated"}, {"text": "稲妻が空を走り、大きな音が響いた。", "target_word": "走り", "complexity_tier": "T3", "furigana": "はしり", "sentence_source": "generated"}, {"text": "ペンが紙の上を走る音だけが、静かな教室に聞こえていた。", "target_word": "走る", "complexity_tier": "T4", "furigana": "はしる", "sentence_source": "generated"}, {"text": "大きな犬に追われた猫は、塀の上を走って逃げた。", "target_word": "走って", "complexity_tier": "T4", "furigana": "はしって", "sentence_source": "generated"}], "morphological_forms": [{"form": "走ります", "label": "活用"}, {"form": "走った", "label": "活用"}, {"form": "走って", "label": "活用"}, {"form": "走らせる", "label": "派生"}, {"form": "走り", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 動物や乗り物が速く動く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51443, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が足を速く動かして、前に進む。", "primary_collocate": "", "pronunciation": "はしる", "ipa": "haɕiɾɯ", "syllable_count": 3, "sentences": [{"text": "私は走るのが速い。", "target_word": "走る", "complexity_tier": "T1", "furigana": "はしる", "sentence_source": "generated"}, {"text": "朝、公園を走ります。", "target_word": "走ります", "complexity_tier": "T2", "furigana": "はしります", "sentence_source": "generated"}, {"text": "バスに遅れて、駅まで走った。", "target_word": "走った", "complexity_tier": "T2", "furigana": "はしった", "sentence_source": "generated"}, {"text": "走ってはいけません。", "target_word": "走って", "complexity_tier": "T2", "furigana": "はしって", "sentence_source": "generated"}, {"text": "子供たちが校庭を走っている。", "target_word": "走っている", "complexity_tier": "T3", "furigana": "はしっている", "sentence_source": "generated"}, {"text": "彼は毎週末、川沿いを十キロ走る。", "target_word": "走る", "complexity_tier": "T3", "furigana": "はしる", "sentence_source": "generated"}, {"text": "走った後で、冷たい水を飲んだ。", "target_word": "走った", "complexity_tier": "T3", "furigana": "はしった", "sentence_source": "generated"}, {"text": "彼女は大会に向けて、毎日走って体力をつけている。", "target_word": "走って", "complexity_tier": "T4", "furigana": "はしって", "sentence_source": "generated"}, {"text": "遅刻しそうになり、彼は駅まで全力で走るはめになった。", "target_word": "走る", "complexity_tier": "T4", "furigana": "はしる", "sentence_source": "generated"}, {"text": "走れば間に合うと思い、私はかばんを持って玄関を飛び出した。", "target_word": "走れば", "complexity_tier": "T5", "furigana": "はしれば", "sentence_source": "generated"}], "morphological_forms": [{"form": "走ります", "label": "活用"}, {"form": "走った", "label": "活用"}, {"form": "走れば", "label": "活用"}, {"form": "走れる", "label": "派生"}, {"form": "走り", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人が足で速く前へ進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が毎日を過ごすこと。また、その日々の過ごし方や、そのまわりの環境。", "primary_collocate": "", "pronunciation": "せいかつ", "ipa": "seːkatsɯ", "syllable_count": 4, "sentences": [{"text": "この効率的な生産システムは、私たちの食生活を支える基盤となっているのです。", "target_word": "生活", "complexity_tier": "T5", "furigana": "せいかつ", "sentence_source": "mined"}, {"text": "彼にとって、毎朝のこの作業は生活のリズムを作る重要な儀式となっている。", "target_word": "生活", "complexity_tier": "T5", "furigana": "せいかつ", "sentence_source": "mined"}, {"text": "新しい生活が始まる。", "target_word": "生活", "complexity_tier": "T1", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "日本の生活に慣れました。", "target_word": "生活", "complexity_tier": "T2", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "田舎で自然に囲まれた生活を送っている。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "都会の生活は便利だが、静かな場所が少ない。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "生活の中で、小さな楽しみを見つけることが大切だ。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "この寮では、学生たちが共同で生活している。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "留学して、初めて一人で生活する大変さを知った。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "生活が変わると、人の考え方も少しずつ変わってくる。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活する", "label": "派生"}, {"form": "生活習慣", "label": "派生"}, {"form": "生活環境", "label": "派生"}, {"form": "生活リズム", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 毎日の過ごし方とその環境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35722, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金を得て、くらしていくこと。また、そのくらしのためのお金や家。", "primary_collocate": "", "pronunciation": "せいかつ", "ipa": "seːkatsɯ", "syllable_count": 4, "sentences": [{"text": "生活が苦しいです。", "target_word": "生活", "complexity_tier": "T2", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "母は働いて、家族の生活を支えている。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "アルバイトをして、自分で生活している。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "年金だけでは生活できない人も多い。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "給料が上がらず、生活は少しも楽にならなかった。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "彼は仕事を失い、生活に困るようになった。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "生活のために、好きな仕事をあきらめる人もいる。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "たくさん貯金があるので、生活の心配はない。", "target_word": "生活", "complexity_tier": "T3", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "家賃が高くて、毎月ぎりぎりの生活が続いている。", "target_word": "生活", "complexity_tier": "T4", "furigana": "せいかつ", "sentence_source": "generated"}, {"text": "病気で働けなくなった祖父は、わずかな貯金で生活するしかなかった。", "target_word": "生活", "complexity_tier": "T5", "furigana": "せいかつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活する", "label": "派生"}, {"form": "生活費", "label": "派生"}, {"form": "生活苦", "label": "派生"}, {"form": "生活保護", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 収入でくらしを立てていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36621, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分に課せられた任務や期待される役割を、きちんとやりとげる。", "primary_collocate": "役割", "pronunciation": "はたす", "ipa": "hatasɯ", "syllable_count": 3, "sentences": [{"text": "家禽の一つであり、人間が管理する家畜として、畜産業界で重要な役割を果たしています。", "target_word": "果たしています", "complexity_tier": "T5", "furigana": "はたしています", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "果たしています", "complexity_tier": "T6", "furigana": "はたしています", "sentence_source": "mined"}, {"text": "彼は大切な役割を果たした。", "target_word": "果たした", "complexity_tier": "T2", "furigana": "はたした", "sentence_source": "generated"}, {"text": "責任を果たします。", "target_word": "果たします", "complexity_tier": "T2", "furigana": "はたします", "sentence_source": "generated"}, {"text": "議長は会議で重要な役割を果たしている。", "target_word": "果たしている", "complexity_tier": "T3", "furigana": "はたしている", "sentence_source": "generated"}, {"text": "親には、子どもを育てる責任を果たす義務がある。", "target_word": "果たす", "complexity_tier": "T4", "furigana": "はたす", "sentence_source": "generated"}, {"text": "彼女はチームの中心として、期待どおりの役割を果たした。", "target_word": "果たした", "complexity_tier": "T4", "furigana": "はたした", "sentence_source": "generated"}, {"text": "義務を果たさない人は、信用を失ってしまう。", "target_word": "果たさない", "complexity_tier": "T4", "furigana": "はたさない", "sentence_source": "generated"}, {"text": "この川は、町の発展に大きな役割を果たしてきた。", "target_word": "果たしてきた", "complexity_tier": "T4", "furigana": "はたしてきた", "sentence_source": "generated"}, {"text": "新しい委員は、その任務を立派に果たして、皆に感謝された。", "target_word": "果たして", "complexity_tier": "T4", "furigana": "はたして", "sentence_source": "generated"}], "morphological_forms": [{"form": "果たします", "label": "活用"}, {"form": "果たした", "label": "活用"}, {"form": "果たして", "label": "活用"}, {"form": "果たさない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 任された役割や責任をやり遂げる", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36620, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "約束や願い、目的などを、最後まで実現させる。", "primary_collocate": "約束", "pronunciation": "はたす", "ipa": "hatasɯ", "syllable_count": 3, "sentences": [{"text": "友達との約束を果たした。", "target_word": "果たした", "complexity_tier": "T2", "furigana": "はたした", "sentence_source": "generated"}, {"text": "彼は目的を果たして、国に帰った。", "target_word": "果たして", "complexity_tier": "T3", "furigana": "はたして", "sentence_source": "generated"}, {"text": "やっと念願を果たしました。", "target_word": "果たしました", "complexity_tier": "T2", "furigana": "はたしました", "sentence_source": "generated"}, {"text": "二十年ぶりの再会を果たした。", "target_word": "果たした", "complexity_tier": "T2", "furigana": "はたした", "sentence_source": "generated"}, {"text": "チームは初めての優勝を果たした。", "target_word": "果たした", "complexity_tier": "T2", "furigana": "はたした", "sentence_source": "generated"}, {"text": "約束を果たさないと、信用を失う。", "target_word": "果たさない", "complexity_tier": "T4", "furigana": "はたさない", "sentence_source": "generated"}, {"text": "目的を果たすために、彼は何度も海を渡った。", "target_word": "果たす", "complexity_tier": "T3", "furigana": "はたす", "sentence_source": "generated"}, {"text": "母との約束を果たせず、ずっと心が痛んでいた。", "target_word": "果たせず", "complexity_tier": "T4", "furigana": "はたせず", "sentence_source": "generated"}, {"text": "長い旅の末に、彼女はついに復讐を果たすことができた。", "target_word": "果たす", "complexity_tier": "T4", "furigana": "はたす", "sentence_source": "generated"}, {"text": "約束を果たすまでは、国には帰れないと彼は決めていた。", "target_word": "果たす", "complexity_tier": "T4", "furigana": "はたす", "sentence_source": "generated"}], "morphological_forms": [{"form": "果たします", "label": "活用"}, {"form": "果たした", "label": "活用"}, {"form": "果たさない", "label": "活用"}, {"form": "果たせず", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 約束や願いを最後まで実現する", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "材料や原料を加工して、物を作り出すこと。", "primary_collocate": "", "pronunciation": "せいさん", "ipa": "seːsaɴ", "syllable_count": 4, "sentences": [{"text": "この効率的な生産システムは、私たちの食生活を支える基盤となっているのです。", "target_word": "生産", "complexity_tier": "T5", "furigana": "せいさん", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "生産", "complexity_tier": "T6", "furigana": "せいさん", "sentence_source": "mined"}, {"text": "この町では米の生産が盛んです。", "target_word": "生産", "complexity_tier": "T2", "furigana": "せいさん", "sentence_source": "generated"}, {"text": "この会社は新しい車を生産しています。", "target_word": "生産しています", "complexity_tier": "T2", "furigana": "せいさんしています", "sentence_source": "generated"}, {"text": "生産を増やすために、機械を買った。", "target_word": "生産", "complexity_tier": "T3", "furigana": "せいさん", "sentence_source": "generated"}, {"text": "台風のせいで、果物の生産は大きく減った。", "target_word": "生産", "complexity_tier": "T3", "furigana": "せいさん", "sentence_source": "generated"}, {"text": "工場では毎日千個の部品が生産される。", "target_word": "生産される", "complexity_tier": "T4", "furigana": "せいさんされる", "sentence_source": "generated"}, {"text": "需要に合わせて生産を調整することで、無駄をなくせる。", "target_word": "生産", "complexity_tier": "T4", "furigana": "せいさん", "sentence_source": "generated"}, {"text": "国内で生産された野菜は新鮮で安全だと言われている。", "target_word": "生産された", "complexity_tier": "T4", "furigana": "せいさんされた", "sentence_source": "generated"}, {"text": "ここで生産するより、外国で作るほうが安いらしい。", "target_word": "生産する", "complexity_tier": "T4", "furigana": "せいさんする", "sentence_source": "generated"}], "morphological_forms": [{"form": "生産する", "label": "派生"}, {"form": "生産者", "label": "派生"}, {"form": "生産量", "label": "派生"}, {"form": "生産性", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 材料を加工して物を作り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体や空気の冷たさや熱さの程度を、数値で表したもの。", "primary_collocate": "", "pronunciation": "おんど", "ipa": "oɴdo", "syllable_count": 3, "sentences": [{"text": "鶏の飼育は、温度や餌が厳密に調整された環境で行われます。", "target_word": "温度", "complexity_tier": "T5", "furigana": "おんど", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "温度", "complexity_tier": "T6", "furigana": "おんど", "sentence_source": "mined"}, {"text": "温度が上がった。", "target_word": "温度", "complexity_tier": "T1", "furigana": "おんど", "sentence_source": "generated"}, {"text": "この部屋の温度は二十度です。", "target_word": "温度", "complexity_tier": "T2", "furigana": "おんど", "sentence_source": "generated"}, {"text": "温度を測ります。", "target_word": "温度", "complexity_tier": "T2", "furigana": "おんど", "sentence_source": "generated"}, {"text": "オーブンの温度を百八十度に設定した。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "実験では、温度が変わると結果も変わる。", "target_word": "温度", "complexity_tier": "T4", "furigana": "おんど", "sentence_source": "generated"}, {"text": "水の温度によって、溶ける砂糖の量は変わる。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "温度計で測った温度を、毎日ノートに記録している。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "冷蔵庫の中は、常に四度以下の温度に保たれている。", "target_word": "温度", "complexity_tier": "T4", "furigana": "おんど", "sentence_source": "generated"}], "morphological_forms": [{"form": "温度計", "label": "派生"}, {"form": "温度差", "label": "派生"}, {"form": "温度変化", "label": "派生"}, {"form": "温度管理", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 熱さ冷たさを数値で表したもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: 7 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 羅針盤 (Zipf 3.09), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52)']::text[], '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの冷たさや熱さの度合い。特に、飲み物や食べ物、お湯などで感じるもの。", "primary_collocate": "", "pronunciation": "おんど", "ipa": "oɴdo", "syllable_count": 3, "sentences": [{"text": "お湯の温度がちょうどいいです。", "target_word": "温度", "complexity_tier": "T2", "furigana": "おんど", "sentence_source": "generated"}, {"text": "スープの温度が下がって、冷めてしまった。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "熱いお風呂は、温度が高すぎて入れない。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "この飲み物は、冷たい温度で飲むとおいしい。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "赤ちゃんのミルクは、ちょうどいい温度にしてください。", "target_word": "温度", "complexity_tier": "T3", "furigana": "おんど", "sentence_source": "generated"}, {"text": "熱いお茶と冷たい麦茶では、温度の差がとても大きい。", "target_word": "温度", "complexity_tier": "T4", "furigana": "おんど", "sentence_source": "generated"}, {"text": "コーヒーの温度が低いと、味もずいぶん変わってしまう。", "target_word": "温度", "complexity_tier": "T4", "furigana": "おんど", "sentence_source": "generated"}, {"text": "冷たすぎない温度の水を飲むほうが、体にはやさしいそうだ。", "target_word": "温度", "complexity_tier": "T4", "furigana": "おんど", "sentence_source": "generated"}, {"text": "お風呂の温度は人によって好みが違い、熱いのが好きな人もぬるいのが好きな人もいる。", "target_word": "温度", "complexity_tier": "T5", "furigana": "おんど", "sentence_source": "generated"}, {"text": "彼女は、お茶の温度にこだわって、いつも少し冷ましてから出してくれる。", "target_word": "温度", "complexity_tier": "T5", "furigana": "おんど", "sentence_source": "generated"}], "morphological_forms": [{"form": "温度差", "label": "派生"}, {"form": "適温", "label": "派生"}, {"form": "温度感", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 飲食物や湯で感じる熱さ冷たさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42822, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥の一種で、肉や卵を食べるために飼われることが多い。", "primary_collocate": "", "pronunciation": "にわとり", "ipa": "niwatoɾi", "syllable_count": 4, "sentences": [{"text": "ブロイラーは、食肉を得るために改良された鶏の品種です。", "target_word": "鶏", "complexity_tier": "T4", "furigana": "にわとり", "sentence_source": "mined"}, {"text": "鶏の飼育は、温度や餌が厳密に調整された環境で行われます。", "target_word": "鶏", "complexity_tier": "T5", "furigana": "にわとり", "sentence_source": "mined"}, {"text": "彼が大切にしているのは、動物である鶏たちへの給餌だ。", "target_word": "鶏", "complexity_tier": "T4", "furigana": "にわとり", "sentence_source": "mined"}, {"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "鶏", "complexity_tier": "T6", "furigana": "にわとり", "sentence_source": "mined"}, {"text": "鶏が鳴く。", "target_word": "鶏", "complexity_tier": "T1", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "祖父は庭で鶏を飼っています。", "target_word": "鶏", "complexity_tier": "T2", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "朝、鶏の声で目が覚めた。", "target_word": "鶏", "complexity_tier": "T2", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "この農場では毎朝、鶏に餌をやる。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "鶏は鳥だが、ほとんど空を飛べない。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "唐揚げは鶏の肉を油で揚げた料理だ。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}], "morphological_forms": [{"form": "鶏肉", "label": "派生"}, {"form": "鶏卵", "label": "派生"}, {"form": "鶏小屋", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 肉や卵のために飼う鳥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3e350d-da65-4a7b-a6b3-ffdf039c4d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
