INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36476, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ちがったところをなおして、ぴったりとあうようにすること。", "primary_collocate": null, "pronunciation": "ちょうせい", "ipa": "tɕoːseː", "syllable_count": 4, "sentences": [{"text": "予定を調整します。", "target_word": "調整", "complexity_tier": "T2", "furigana": "よてい ちょうせい", "sentence_source": "generated"}, {"text": "意見の調整は難しいです。", "target_word": "調整", "complexity_tier": "T2", "furigana": "いけん ちょうせい むずか", "sentence_source": "generated"}, {"text": "日程を調整して、会議を開いた。", "target_word": "調整", "complexity_tier": "T3", "furigana": "にってい ちょうせい かいぎ ひら", "sentence_source": "generated"}, {"text": "服の長さを調整してもらった。", "target_word": "調整", "complexity_tier": "T3", "furigana": "ふく なが ちょうせい", "sentence_source": "generated"}, {"text": "調整がうまくいって、全員が集まれた。", "target_word": "調整", "complexity_tier": "T3", "furigana": "ちょうせい ぜんいん あつ", "sentence_source": "generated"}, {"text": "食い違いを調整すれば、話はまとまる。", "target_word": "調整", "complexity_tier": "T4", "furigana": "く ちが ちょうせい はなし", "sentence_source": "generated"}, {"text": "担当者が各部署と調整している。", "target_word": "調整", "complexity_tier": "T3", "furigana": "たんとうしゃ かくぶしょ ちょうせい", "sentence_source": "generated"}, {"text": "調整してから、もう一度送ってください。", "target_word": "調整", "complexity_tier": "T3", "furigana": "ちょうせい いちど おく", "sentence_source": "generated"}, {"text": "時間の調整のため、集合は十時になった。", "target_word": "調整", "complexity_tier": "T4", "furigana": "じかん ちょうせい しゅうごう じゅうじ", "sentence_source": "generated"}, {"text": "ずれの調整方法を教えてください。", "target_word": "調整", "complexity_tier": "T3", "furigana": "ちょうせいほうほう おし", "sentence_source": "generated"}], "morphological_forms": [{"form": "調整する", "label": "活用"}, {"form": "調整中", "label": "派生"}, {"form": "微調整", "label": "派生"}, {"form": "調整役", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ちがいをなおしてぴったり合わせる", "colloc