INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42853, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "数量や程度が非常に少ないことを表す副詞です。", "primary_collocate": null, "pronunciation": "わずか", "ipa": "wazɯka", "syllable_count": 3, "sentences": [{"text": "彼らは驚くべきスピードで成長し、わずか数週間で出荷可能な体重になります。", "target_word": "わずか", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "僅か", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "わずかな時間だ。", "target_word": "わずかな", "complexity_tier": "T1", "furigana": "じかん", "sentence_source": "generated"}, {"text": "お金はわずかです。", "target_word": "わずか", "complexity_tier": "T2", "furigana": "かね", "sentence_source": "generated"}, {"text": "わずかに雨が降った。", "target_word": "わずかに", "complexity_tier": "T2", "furigana": "あめ ふ", "sentence_source": "generated"}, {"text": "差はわずかしかなかった。", "target_word": "わずか", "complexity_tier": "T3", "furigana": "さ", "sentence_source": "generated"}, {"text": "わずか五分で着きました。", "target_word": "わずか", "complexity_tier": "T2", "furigana": "ごふん つ", "sentence_source": "generated"}, {"text": "僅かな希望を信じて待った。", "target_word": "僅かな", "complexity_tier": "T3", "furigana": "わずか きぼう しん ま", "sentence_source": "generated"}, {"text": "彼の成績はわずかに上がった。", "target_word": "わずかに", "complexity_tier": "T3", "furigana": "かれ せいせき あ", "sentence_source": "generated"}, {"text": "残りはわずか二日だと聞いて、焦った。", "target_word": "わずか", "complexity_tier": "T4", "furigana": "のこ ふつか き あせ", "sentence_source": "generated"}, {"text": "食べ物が僅かしか残っていない。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "た もの わずか のこ", "sentence_source": "generated"}, {"text": "わずかなミスが大きな事故につながる。", "target_word": "わずかな", "complexity_tier": "T4", "furigana": "おお じこ", "sentence_source": "generated"}], "morphological_forms": [{"form": "わずかな", "label": "派生"}, {"form": "わずかに", "label": "派生"}, {"form": "わずかしか", "label": "派生"}, {"form": "僅差", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | 数量や程度が非常に少ないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 土塊 (Zipf 1.72)']::text[], 'f96e901f-2f8a-4e7c-91aa-bcd45369805d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51570, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物の分類において、同じ種の中でも、人間が目的に合わせて改良したり選抜したりして作り出した、特定の形質を持つ集団。品種改良によって生まれる。", "primary_collocate": null, "pronunciation": "ひんしゅ", "ipa": "çiɴɕɯ", "syllable_count": 3, "sentences": [{"text": "ブロイラーは、食肉を得るために改良された鶏の品種です。", "target_word": "品種", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "品種", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "米の新しい品種が生まれた。", "target_word": "品種", "complexity_tier": "T3", "furigana": "こめ あたら ひんしゅ う", "sentence_source": "generated"}, {"text": "この品種は寒さに強いです。", "target_word": "品種", "complexity_tier": "T2", "furigana": "ひんしゅ さむ つよ", "sentence_source": "generated"}, {"text": "農家は病気に強い品種を選んだ。", "target_word": "品種", "complexity_tier": "T3", "furigana": "のうか びょうき つよ ひんしゅ えら", "sentence_source": "generated"}, {"text": "研究者が品種を改良して、甘いいちごを作った。", "target_word": "品種", "complexity_tier": "T4", "furigana": "けんきゅうしゃ ひんしゅ かいりょう あま つく", "sentence_source": "generated"}, {"text": "品種ごとに味が違う。", "target_word": "品種", "complexity_tier": "T2", "furigana": "ひんしゅ あじ ちが", "sentence_source": "generated"}, {"text": "この犬の品種は、人の手で作られた。", "target_word": "品種", "complexity_tier": "T4", "furigana": "いぬ ひんしゅ ひと て つく", "sentence_source": "generated"}, {"text": "品種の違いで収穫の時期が変わる。", "target_word": "品種", "complexity_tier": "T4", "furigana": "ひんしゅ ちが しゅうかく じき か", "sentence_source": "generated"}, {"text": "トマトの品種を比べて、一番甘いものを買った。", "target_word": "品種", "complexity_tier": "T4", "furigana": "ひんしゅ くら いちばん あま か", "sentence_source": "generated"}], "morphological_forms": [{"form": "品種名", "label": "派生"}, {"form": "新品種", "label": "派生"}, {"form": "品種改良", "label": "派生"}, {"form": "在来品種", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が改良して作った生物の種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], 'f96e901f-2f8a-4e7c-91aa-bcd45369805d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51569, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "どうぶつやしょくぶつのなかで、とくべつなせいしつをもつしゅるいのこと。", "primary_collocate": null, "pronunciation": "ひんしゅ", "ipa": "çiɴɕɯ", "syllable_count": 3, "sentences": [{"text": "犬にはたくさんの品種がある。", "target_word": "品種", "complexity_tier": "T2", "furigana": "いぬ ひんしゅ", "sentence_source": "generated"}, {"text": "この花は珍しい品種です。", "target_word": "品種", "complexity_tier": "T2", "furigana": "はな めずら ひんしゅ", "sentence_source": "generated"}, {"text": "猫の品種を調べた。", "target_word": "品種", "complexity_tier": "T2", "furigana": "ねこ ひんしゅ しら", "sentence_source": "generated"}, {"text": "どの品種が好きですか。", "target_word": "品種", "complexity_tier": "T2", "furigana": "ひんしゅ す", "sentence_source": "generated"}, {"text": "品種によって、毛の長さが違う。", "target_word": "品種", "complexity_tier": "T3", "furigana": "ひんしゅ け なが ちが", "sentence_source": "generated"}, {"text": "バラの品種は、色も形もさまざまだ。", "target_word": "品種", "complexity_tier": "T3", "furigana": "ひんしゅ いろ かたち", "sentence_source": "generated"}, {"text": "同じ品種でも、性格は一匹ずつ違う。", "target_word": "品種", "complexity_tier": "T3", "furigana": "おな ひんしゅ せいかく いっぴき ちが", "sentence_source": "generated"}, {"text": "この品種の馬は足が速いことで知られている。", "target_word": "品種", "complexity_tier": "T4", "furigana": "ひんしゅ うま あし はや し", "sentence_source": "generated"}, {"text": "品種の名前を図鑑で確認した。", "target_word": "品種", "complexity_tier": "T3", "furigana": "ひんしゅ なまえ ずかん かくにん", "sentence_source": "generated"}, {"text": "珍しい品種のりんごを見つけて、買って帰った。", "target_word": "品種", "complexity_tier": "T4", "furigana": "めずら ひんしゅ み か かえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "品種名", "label": "派生"}, {"form": "新品種", "label": "派生"}, {"form": "品種別", "label": "派生"}, {"form": "珍品種", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 動植物の特別な性質を持つ種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96e901f-2f8a-4e7c-91aa-bcd45369805d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51744, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や道具を使って、物に力を加えてたたく動作。", "primary_collocate": null, "pronunciation": "うつ", "ipa": "ɯtsɯ", "syllable_count": 2, "sentences": [{"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "打ち", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "打つ", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "金づちで釘を打ちます。", "target_word": "打ち", "complexity_tier": "T2", "furigana": "くぎ", "sentence_source": "generated"}, {"text": "太鼓を打つ音が聞こえた。", "target_word": "打つ", "complexity_tier": "T3", "furigana": "たいこ おと き", "sentence_source": "generated"}, {"text": "大工は柱に釘を打っていた。", "target_word": "打って", "complexity_tier": "T3", "furigana": "だいく はしら くぎ", "sentence_source": "generated"}, {"text": "父はハンマーで杭を打っている。", "target_word": "打って", "complexity_tier": "T3", "furigana": "ちち くい う", "sentence_source": "generated"}, {"text": "釘を打たないで、ひもでつるした。", "target_word": "打たない", "complexity_tier": "T3", "furigana": "くぎ", "sentence_source": "generated"}, {"text": "石を打って火花を出した。", "target_word": "打って", "complexity_tier": "T3", "furigana": "いし ひばな だ", "sentence_source": "generated"}, {"text": "鐘が打たれると、村の人が集まった。", "target_word": "打たれる", "complexity_tier": "T4", "furigana": "かね むら ひと あつ", "sentence_source": "generated"}, {"text": "太鼓は強く打つほど大きな音が出る。", "target_word": "打つ", "complexity_tier": "T4", "furigana": "たいこ つよ おお おと で", "sentence_source": "generated"}], "morphological_forms": [{"form": "打った", "label": "活用"}, {"form": "打って", "label": "活用"}, {"form": "打たない", "label": "活用"}, {"form": "打たれる", "label": "活用"}, {"form": "打ち", "label": "活用"}], "register": "plain", "sense_finge