INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38437, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事の程度が非常に激しかったり、条件がとても厳しかったりする様子。また、人に対して要求が多く、簡単に許さない様子。", "primary_collocate": null, "pronunciation": "きびしい", "ipa": "kibiɕiː", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "厳し", "complexity_tier": "T6", "furigana": "きびし", "sentence_source": "mined"}, {"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "厳しい", "complexity_tier": "T6", "furigana": "きびしい", "sentence_source": "mined"}, {"text": "この冬の寒さはとても厳しいです。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "父は私に厳しく、門限を守らせた。", "target_word": "厳しく", "complexity_tier": "T3", "furigana": "きびしく", "sentence_source": "generated"}, {"text": "厳しい暑さの中、畑で作業を続けた。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "彼女はいつも自分に厳しい。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "山の厳しい自然に耐えて育った木だ。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "この会社は残業の管理が厳しい。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "厳しく叱られても、彼は笑っていた。", "target_word": "厳しく", "complexity_tier": "T3", "furigana": "きびしく", "sentence_source": "generated"}, {"text": "厳しかった夏が、やっと終わった。", "target_word": "厳しかった", "complexity_tier": "T3", "furigana": "きびしかった", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳しく", "label": "活用"}, {"form": "厳しかった", "label": "活用"}, {"form": "厳しさ", "label": "派生"}, {"form": "厳しくない", "label": "活用"}], "register": "plain", "sense_fingerprint": "形容詞 | 自然や人の要求が非常に激しい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38436, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "とても大変で、ゆるくないこと。", "primary_collocate": null, "pronunciation": "きびしい", "ipa": "kibiɕiː", "syllable_count": 4, "sentences": [{"text": "生活が厳しくて、新しい服は買えない。", "target_word": "厳しくて", "complexity_tier": "T3", "furigana": "きびしくて", "sentence_source": "generated"}, {"text": "試験の競争は厳しいです。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "今年は厳しい戦いになりそうだ。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "厳しい練習を毎日続けている。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "店の経営は厳しい状況だ。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "厳しい道のりだったが、やりきった。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "この仕事は思ったより厳しかった。", "target_word": "厳しかった", "complexity_tier": "T3", "furigana": "きびしかった", "sentence_source": "generated"}, {"text": "厳しい条件でも、彼は引き受けた。", "target_word": "厳しい", "complexity_tier": "T3", "furigana": "きびしい", "sentence_source": "generated"}, {"text": "厳しさを増す競争に、みんなが焦っている。", "target_word": "厳しさ", "complexity_tier": "T3", "furigana": "きびしさ", "sentence_source": "generated"}, {"text": "現実は厳しくて、夢だけでは進めない。", "target_word": "厳しくて", "complexity_tier": "T3", "furigana": "きびしくて", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳しく", "label": "活用"}, {"form": "厳しかった", "label": "活用"}, {"form": "厳しさ", "label": "派生"}, {"form": "厳しくない", "label": "活用"}], "register": "plain", "sense_fingerprint": "形容詞 | 状況や条件がきつく余裕がない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41281, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "abstract", "definition": "年齢を十年ごとに区切った範囲を表す接尾辞（十代、二十代など）。", "primary_collocate": null, "pronunciation": "だい", "ipa": "dai", "syllable_count": 2, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "代", "complexity_tier": "T6", "furigana": "だい", "sentence_source": "mined"}, {"text": "十代の人が初めてステージに立ちます。", "target_word": "代", "complexity_tier": "T6", "furigana": "だい", "sentence_source": "mined"}, {"text": "父は四十代で、母は三十代です。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "二十代の若者が増えている。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "彼女は五十代になっても元気だ。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "この歌は、十代に人気があります。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "三十代の私も、毎日走っています。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "うちの店は、六十代のお客さんが多い。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "二十代前半のうちに、海外へ行きたい。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "十代のころ、毎日サッカーをした。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}], "morphological_forms": [{"form": "十代", "label": "派生"}, {"form": "二十代", "label": "派生"}, {"form": "三十代", "label": "派生"}, {"form": "四十代", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 年齢を十年ごとに区切る言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41280, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "家や店などを親から子へ受け継いでいく、それぞれの世代や当主の時期。", "primary_collocate": null, "pronunciation": "だい", "ipa": "dai", "syllable_count": 2, "sentences": [{"text": "この店は祖父の代から続いている。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "父の代で、畑を少し広げた。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "私の代で、この店を閉めたくない。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "三代続く農家に生まれた。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "先祖の代から、この土地に住んでいる。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "親の代とは、考え方が違う。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "代が変わっても、味は同じだ。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "何代も前の話だと聞いている。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "次の代に、畑を引き渡したい。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}, {"text": "この家は、七代にわたって続いた。", "target_word": "代", "complexity_tier": "T3", "furigana": "だい", "sentence_source": "generated"}], "morphological_forms": [{"form": "三代", "label": "助数詞"}, {"form": "五代", "label": "助数詞"}, {"form": "代々", "label": "派生"}, {"form": "代替わり", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 親から子へ続く世代や当主の代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35537, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物・動物・人の世話をして、大きく成長させる。", "primary_collocate": null, "pronunciation": "そだてる", "ipa": "sodateɾɯ", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "育てる", "complexity_tier": "T6", "furigana": "そだてる", "sentence_source": "mined"}, {"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "育てる", "complexity_tier": "T6", "furigana": "そだてる", "sentence_source": "mined"}, {"text": "農家の人は、おいしい米を育てている。", "target_word": "育てている", "complexity_tier": "T3", "furigana": "そだてている", "sentence_source": "generated"}, {"text": "両親は私を大切に育ててくれた。", "target_word": "育てて", "complexity_tier": "T3", "furigana": "そだてて", "sentence_source": "generated"}, {"text": "犬を育てるのは、とても大変です。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}, {"text": "彼は新人をていねいに育てる。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}, {"text": "子どもを育てながら、働いている。", "target_word": "育て", "complexity_tier": "T3", "furigana": "そだて", "sentence_source": "generated"}, {"text": "牛を育てて、牛乳を作る農家もある。", "target_word": "育てて", "complexity_tier": "T3", "furigana": "そだてて", "sentence_source": "generated"}, {"text": "育てた野菜を、近所の人に配った。", "target_word": "育てた", "complexity_tier": "T3", "furigana": "そだてた", "sentence_source": "generated"}, {"text": "人を育てる仕事に、やりがいを感じる。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}], "morphological_forms": [{"form": "育てて", "label": "活用"}, {"form": "育てた", "label": "活用"}, {"form": "育てられる", "label": "活用"}, {"form": "育て方", "label": "派生"}, {"form": "育ての親", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 作物や動物や人を世話して成長させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35536, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物に水や光を与えて、大きく成長させる。", "primary_collocate": null, "pronunciation": "そだてる", "ipa": "sodateɾɯ", "syllable_count": 4, "sentences": [{"text": "毎日水をあげて、花を育てています。", "target_word": "育て", "complexity_tier": "T3", "furigana": "そだて", "sentence_source": "generated"}, {"text": "ひまわりを育てるには、太陽の光が必要だ。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}, {"text": "ベランダで小さなトマトを育てる。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}, {"text": "朝顔の種をまいて、育てた。", "target_word": "育てた", "complexity_tier": "T3", "furigana": "そだてた", "sentence_source": "generated"}, {"text": "水と光で、豆を育てる実験をした。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}, {"text": "育てている花に、毎朝水をやる。", "target_word": "育てている", "complexity_tier": "T3", "furigana": "そだてている", "sentence_source": "generated"}, {"text": "庭でハーブを育てたい。", "target_word": "育て", "complexity_tier": "T3", "furigana": "そだて", "sentence_source": "generated"}, {"text": "鉢を窓辺に置いて、育てている。", "target_word": "育てている", "complexity_tier": "T3", "furigana": "そだてている", "sentence_source": "generated"}, {"text": "育てやすい花を、母に教えてもらった。", "target_word": "育てやすい", "complexity_tier": "T3", "furigana": "そだてやすい", "sentence_source": "generated"}, {"text": "きれいな花を育てるのが、私の趣味です。", "target_word": "育てる", "complexity_tier": "T3", "furigana": "そだてる", "sentence_source": "generated"}], "morphological_forms": [{"form": "育てて", "label": "活用"}, {"form": "育てた", "label": "活用"}, {"form": "育てられる", "label": "活用"}, {"form": "育て方", "label": "派生"}, {"form": "育ての親", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 水や光を与えて植物を大きくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "高等学校の略。中学校を卒業した後、さらに学ぶための学校。通常15歳から18歳までの生徒が通う。", "primary_collocate": null, "pronunciation": "こうこう", "ipa": "koːkoː", "syllable_count": 4, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "高校", "complexity_tier": "T6", "furigana": "こうこう", "sentence_source": "mined"}, {"text": "高校生は学校でスポーツをします。", "target_word": "高校", "complexity_tier": "T6", "furigana": "こうこう", "sentence_source": "mined"}, {"text": "兄は来年、高校を卒業します。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校の体育館で、大会が開かれた。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "この高校には、千人の生徒が通っている。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "十五歳から十八歳の生徒が高校で学ぶ。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校の先生は、進路の相談に乗ってくれた。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "私の高校は、駅から歩いて十分だ。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校時代の友だちと、久しぶりに会った。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校で野球部に入った。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "高校生", "label": "派生"}, {"form": "高校時代", "label": "派生"}, {"form": "高校野球", "label": "派生"}, {"form": "高校三年生", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 十五歳から十八歳が学ぶ高等学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51425, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "高校は、中学校の次に行く学校です。", "primary_collocate": null, "pronunciation": "こうこう", "ipa": "koːkoː", "syllable_count": 4, "sentences": [{"text": "中学を出たら、高校に行きます。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "姉は来月、高校に入る。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校に進むために、毎日勉強した。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "弟は高校の試験を受けるつもりだ。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "どの高校に行くか、まだ決めていない。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校へ行くには、バスで三十分かかる。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "来年の春から、高校に通います。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "高校に受かって、家族が喜んだ。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "中学の次は、高校です。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}, {"text": "友だちと同じ高校を目指している。", "target_word": "高校", "complexity_tier": "T3", "furigana": "こうこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "高校生", "label": "派生"}, {"form": "高校時代", "label": "派生"}, {"form": "高校野球", "label": "派生"}, {"form": "高校三年生", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 中学校の次に進む学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51556, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体や粉状のものが、表面に広がってつくこと。特に、泥や血などが全身に付着する様子を表す。", "primary_collocate": null, "pronunciation": "まみれる", "ipa": "mamiɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "まみれ", "complexity_tier": "T6", "furigana": "まみれ", "sentence_source": "mined"}, {"text": "彼は泥にまみれながら、日々屋外にて植物の萌芽を見守る。", "target_word": "まみれ", "complexity_tier": "T6", "furigana": "まみれ", "sentence_source": "mined"}, {"text": "傷だらけの手が、血にまみれていた。", "target_word": "まみれていた", "complexity_tier": "T3", "furigana": "まみれていた", "sentence_source": "generated"}, {"text": "小麦粉にまみれて、パンを作った。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "彼は汗と油にまみれて働いている。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "ほこりにまみれた本を、棚から出した。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "全身が泥にまみれたまま、家に帰った。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "粉にまみれても、子どもは楽しそうだ。", "target_word": "まみれても", "complexity_tier": "T3", "furigana": "まみれても", "sentence_source": "generated"}, {"text": "砂にまみれた靴を、水で洗った。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "インクにまみれた手で、紙に触ってしまった。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}], "morphological_forms": [{"form": "まみれる", "label": "活用"}, {"form": "まみれた", "label": "活用"}, {"form": "まみれて", "label": "活用"}, {"form": "まみれない", "label": "活用"}, {"form": "泥まみれ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 血や粉や泥が全身に一面につく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51555, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "からだやようふくに、どろやえきがたくさんつくこと。", "primary_collocate": null, "pronunciation": "まみれる", "ipa": "mamiɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "泥にまみれて、服が真っ黒になった。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "子どもたちは泥にまみれて遊んだ。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "雨の日、ズボンが泥にまみれた。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "サッカーで転んで、体が泥にまみれた。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "ジュースにまみれたシャツを洗う。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}, {"text": "汗にまみれて、走り続けた。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "犬が散歩の後、泥にまみれて帰ってきた。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "体じゅう泥にまみれても、彼は笑った。", "target_word": "まみれても", "complexity_tier": "T3", "furigana": "まみれても", "sentence_source": "generated"}, {"text": "服がペンキにまみれてしまった。", "target_word": "まみれて", "complexity_tier": "T3", "furigana": "まみれて", "sentence_source": "generated"}, {"text": "泥にまみれた靴を、玄関で脱いだ。", "target_word": "まみれた", "complexity_tier": "T3", "furigana": "まみれた", "sentence_source": "generated"}], "morphological_forms": [{"form": "まみれる", "label": "活用"}, {"form": "まみれた", "label": "活用"}, {"form": "まみれて", "label": "活用"}, {"form": "まみれない", "label": "活用"}, {"form": "泥まみれ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 体や服に泥や液がたくさんつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36599, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が成り立っているための、決まった構造や、動作の流れのこと。", "primary_collocate": null, "pronunciation": "しくみ", "ipa": "ɕikɯmi", "syllable_count": 3, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "仕組み", "complexity_tier": "T6", "furigana": "しくみ", "sentence_source": "mined"}, {"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "仕組み", "complexity_tier": "T6", "furigana": "しくみ", "sentence_source": "mined"}, {"text": "この制度の仕組みを説明します。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "銀行の仕組みを、学校で習った。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "税金の仕組みは、少しむずかしい。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "新しい仕組みのおかげで、仕事が早くなった。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "町の人が助け合う仕組みを作った。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "仕組みを理解すれば、使い方も分かる。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "会員になると割引になる仕組みだ。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "地震が起こる仕組みを調べている。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕組み", "label": "派生"}, {"form": "仕組む", "label": "活用"}, {"form": "仕組まれた", "label": "活用"}, {"form": "仕組みづくり", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 制度や社会が成り立つ決まった構造", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36598, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かが動いたり、変わったりするための決まったやり方や形のことです。", "primary_collocate": null, "pronunciation": "しくみ", "ipa": "ɕikɯmi", "syllable_count": 3, "sentences": [{"text": "この時計の仕組みは、とても面白い。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "おもちゃが動く仕組みを調べた。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "エアコンが部屋を冷やす仕組みを知りたい。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "カメラの仕組みを、兄が教えてくれた。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "体が汗を出す仕組みは、よくできている。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "ドアが自動で開く仕組みを見た。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "虹ができる仕組みを、絵でかいた。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "この機械は、簡単な仕組みで動く。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "仕組みが単純なので、すぐ直せた。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}, {"text": "ふしぎな仕組みの箱を、祖父が作った。", "target_word": "仕組み", "complexity_tier": "T3", "furigana": "しくみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕組み", "label": "派生"}, {"form": "仕組む", "label": "活用"}, {"form": "仕組まれた", "label": "活用"}, {"form": "仕組みづくり", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物が動くための形や働き方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28ef692-eecd-497b-b8da-3bda0638dc3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38437, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厳しい", "is_correct": true, "explanation": "『厳しい』が見出し語で、聞こえた音と一致する。"}, {"text": "険しい", "is_correct": false, "explanation": "『険しい』は音が違うので、聞こえた語ではない。"}, {"text": "久しい", "is_correct": false, "explanation": "『久しい』は音が違うので、聞こえた語ではない。"}, {"text": "怪しい", "is_correct": false, "explanation": "『怪しい』は音が違うので、聞こえた語ではない。"}], "explanations": {"厳しい": "『厳しい』が見出し語で、聞こえた音と一致する。", "険しい": "『険しい』は音が違うので、聞こえた語ではない。", "久しい": "『久しい』は音が違うので、聞こえた語ではない。", "怪しい": "『怪しい』は音が違うので、聞こえた語ではない。"}, "sentence_index": null, "correct_answer": "厳しい"}, "level_3": {"options": [{"text": "厳し", "is_correct": true, "explanation": "この文脈に自然に合い、意味が通る。"}, {"text": "忙し", "is_correct": false, "explanation": "この文に入れると意味が合わない。"}, {"text": "嬉し", "is_correct": false, "explanation": "この文に入れると意味が合わない。"}, {"text": "騒がし", "is_correct": false, "explanation": "この文に入れると意味が合わない。"}], "explanations": {"厳し": "この文脈に自然に合い、意味が通る。", "忙し": "この文に入れると意味が合わない。", "嬉し": "この文に入れると意味が合わない。", "騒がし": "この文に入れると意味が合わない。"}, "sentence_index": 0, "correct_answer": "厳し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は味が厳しくて、とてもおいしい。", "explanation": "味の良さには使わない。『厳しい』は程度の激しさや要求の高さを表す。"}, {"text": "この箱は厳しくて、持ち上げられない。", "explanation": "重さを表す語ではない。『重い』と言うべきだ。"}, {"text": "厳しいケーキを食べて、お腹がいっぱいになった。", "explanation": "食べ物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37135006-554c-4ff5-b226-163e9d8971ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
